from itertools import permutations

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sum_of_divisors(n):
    divs = get_divisors(n)
    return sum(divs)

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_permutation_problem(divisors):
    n = len(divisors)

    # Optimization: Check if the largest square smaller than sigma(m) allows for a path.
    # However, since n is small (max 8 for m<=30), we'll rely on searching.

    # We use backtracking search.

    def find_path(current_sum, remaining_divisors, path):
        # Base case: All divisors used
        if not remaining_divisors:
            # We already know current_sum (which is sigma(m)) is a square, 
            # so we only need to check the final step consistency here.
            # Since we enforce the square property at each step, this should be fine.
            return True

        # Try adding every remaining divisor
        for i in range(len(remaining_divisors)):
            divisor = remaining_divisors[i]
            next_sum = current_sum + divisor

            if is_square(next_sum):
                # Prepare for next recursive call
                next_remaining = remaining_divisors[:i] + remaining_divisors[i+1:]

                if find_path(next_sum, next_remaining, path + [divisor]):
                    return True

        return False

    # The first element must be a square itself.
    for d1 in divisors:
        if is_square(d1):
            remaining = [d for d in divisors if d != d1]
            if find_path(d1, remaining, [d1]):
                return True

    return False

