import math

def sigma(n):
    """Calculates the sum of divisors of n."""
    if n <= 0:
        return 0
    s = 1
    temp_n = n
    i = 2
    while i * i <= temp_n:
        if temp_n % i == 0:
            p = i
            count = 0
            while temp_n % p == 0:
                count += 1
                temp_n //= p
            s *= (p**(count + 1) - 1) // (p - 1)
        i += 1
    if temp_n > 1:
        s *= (temp_n**2 - 1) // (temp_n - 1)
    return s

def is_perfect_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def get_divisors(n):
